contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val) public payable {
        uint256 before = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterVal = c.MinSum(); if (__ESBMC_reverted()) return;
        assert((!reverted && afterVal == val) || (reverted && afterVal == before));
    }

    receive() external payable {}
}

